from z3 import *

n = 12
X = [[Int(f"x_{i}_{j}") for j in range(n)] for i in range(n)]

s = Solver()

# Domain
for i in range(n):
    for j in range(n):
        s.add(X[i][j] >= 0, X[i][j] < n)

# Latin square
for i in range(n):
    s.add(Distinct(X[i]))
for j in range(n):
    s.add(Distinct([X[i][j] for i in range(n)]))

# Idempotent
for i in range(n):
    s.add(X[i][i] == i)

# QG3: x[ x[i][j] ][ x[j][i] ] = i
# We can encode this using uninterpreted functions or just boolean variables,
# but Z3 can handle array/function or just nested indexing if we use a function.
# Let's use a Function.
f = Function('f', IntSort(), IntSort(), IntSort())

for i in range(n):
    for j in range(n):
        s.add(f(i, j) == X[i][j])

for i in range(n):
    for j in range(n):
        s.add(f(f(i, j), f(j, i)) == i)

# Symmetry breaking?
# QG3 implies x[x[i][j]][x[j][i]] = i.
# If we swap i and j, x[x[j][i]][x[i][j]] = j.
# So if x[i][j] = u and x[j][i] = v, then x[u][v] = i and x[v][u] = j.

s.set("timeout", 50000)
if s.check() == sat:
    m = s.model()
    res = []
    for i in range(n):
        for j in range(n):
            res.append(m.evaluate(X[i][j]).as_long())
    print("SAT")
    print(res)
else:
    print("UNSAT or TIMEOUT")

from pysat.solvers import Glucose4
import time

n = 12

def var(i, j, k):
    return i * n * n + j * n + k + 1

solver = Glucose4()

# Exactly one k for each i, j
for i in range(n):
    for j in range(n):
        solver.add_clause([var(i, j, k) for k in range(n)])
        for k1 in range(n):
            for k2 in range(k1 + 1, n):
                solver.add_clause([-var(i, j, k1), -var(i, j, k2)])

# Exactly one j for each i, k
for i in range(n):
    for k in range(n):
        solver.add_clause([var(i, j, k) for j in range(n)])
        for j1 in range(n):
            for j2 in range(j1 + 1, n):
                solver.add_clause([-var(i, j1, k), -var(i, j2, k)])

# Exactly one i for each j, k
for j in range(n):
    for k in range(n):
        solver.add_clause([var(i, j, k) for i in range(n)])
        for i1 in range(n):
            for i2 in range(i1 + 1, n):
                solver.add_clause([-var(i1, j, k), -var(i2, j, k)])

# Idempotent
for i in range(n):
    solver.add_clause([var(i, i, i)])

# QG3: x[i][j] = u and x[j][i] = v => x[u][v] = i
for i in range(n):
    for j in range(n):
        for u in range(n):
            for v in range(n):
                solver.add_clause([-var(i, j, u), -var(j, i, v), var(u, v, i)])

print("Solving...")
start = time.time()
if solver.solve():
    print("SAT")
    model = solver.get_model()
    res = []
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if model[var(i, j, k) - 1] > 0:
                    res.append(k)
    print(res)
else:
    print("UNSAT")
print("Time:", time.time() - start)

